insert into public.questions (id, pack_id, theme, type, prompt, unit, answer, items, year, subject, source, source_url, perishable, difficulty, status, verified_at, review_due_at, notes)
values
('football-p1-001', 'football', 'football', 'number'::public.question_type, 'Combien de spectateurs (en milliers) ont assisté aux matchs de la Coupe du monde 2026, l’édition la plus fréquentée de l’histoire ?', 'milliers', 6811, null, false, 'cdm2026-affluence', 'FIFA', 'https://ipt.fifa.com/organisation/news/spain-crowned-world-cup-2026-champions-new-york-new-jersey', false, 2, 'published'::public.question_status, '2026-10-16', null, 'FIFA : 6 810 966 spectateurs sur 104 matchs (ancien record : 3 587 538 en 1994).'),
('football-p1-002', 'football', 'football', 'number'::public.question_type, 'Combien de buts ont été marqués lors de la Coupe du monde 2026, l’édition la plus prolifique de l’histoire ?', 'buts', 308, null, false, 'cdm2026-buts', 'FIFA', 'https://ipt.fifa.com/organisation/news/spain-crowned-world-cup-2026-champions-new-york-new-jersey', false, 2, 'published'::public.question_status, '2026-10-16', null, 'FIFA : 308 buts en 104 matchs (ancien record 172 au Qatar 2022).'),
('football-p1-003', 'football', 'football', 'number'::public.question_type, 'Combien de matchs ont été disputés lors de la Coupe du monde 2026, la plus grande de l’histoire avec 48 équipes ?', 'matchs', 104, null, false, 'cdm2026-matchs', 'FIFA', 'https://ipt.fifa.com/organisation/news/spain-crowned-world-cup-2026-champions-new-york-new-jersey', false, 1, 'published'::public.question_status, '2026-10-16', null, 'FIFA : premier tournoi à 48 équipes et 104 matchs (64 auparavant).'),
('football-p1-004', 'football', 'football', 'number'::public.question_type, 'Combien de buts Kylian Mbappé comptait-il en équipe de France à l’issue de la Coupe du monde 2026, record absolu des Bleus ?', 'buts', 66, null, false, 'mbappe-bleus', 'Paris Match (AFP)', 'https://www.parismatch.be/actualites/sport/2026/07/20/coupe-du-monde-2026-kylian-mbappe-finit-meilleur-buteur-du-tournoi-avec-10-buts-ODQHVCRMBVD47GMBWM4I34MLOQ/', true, 1, 'published'::public.question_status, '2026-10-16', '2027-04-16', '66 buts en 107 sélections après la petite finale France-Angleterre (4-6) ; record de Giroud (57) battu le 16 juin 2026. Énoncé daté à la fin du Mondial pour éviter les matchs de septembre.'),
('football-p1-005', 'football', 'football', 'number'::public.question_type, 'Combien de buts Delio Onnis a-t-il marqués en championnat de France, le record absolu de la Ligue 1 ?', 'buts', 299, null, false, 'onnis', 'LFP (ligue1.com)', 'https://ligue1.com/fr/articles/l1_article_310-', false, 2, 'published'::public.question_status, '2026-10-16', null, 'LFP : 299 buts (1971-1986), devant Lacombe (255).'),
('football-p1-006', 'football', 'football', 'number'::public.question_type, 'Combien de matchs de première division Mickaël Landreau a-t-il disputés, le record de l’histoire de la Ligue 1 ?', 'matchs', 618, null, false, 'landreau', 'FFF', 'https://www.fff.fr/article/1040-17-mai-2014-la-reverence-du-recordman.html', false, 2, 'published'::public.question_status, '2026-10-16', null, 'FFF : 618 matchs (Nantes 335, Lille 119, PSG 114, Bastia 50). Le classement LFP donne 617 (Bastia 49) : écart d’une unité.'),
('football-p1-007', 'football', 'football', 'number'::public.question_type, 'Pendant combien de minutes Gaëtan Huard (Bordeaux) est-il resté sans encaisser de but en 1992-1993, le record de la Ligue 1 ?', 'min', 1176, null, false, 'huard', 'LFP (ligue1.com)', 'https://ligue1.com/fr/articles/l1_article_182-', false, 3, 'published'::public.question_status, '2026-10-16', null, 'LFP : 1 176 minutes du 19/12/1992 au 10/04/1993 ; Enyeama 2e (1 106).'),
('football-p1-008', 'football', 'football', 'number'::public.question_type, 'Combien de matchs de Ligue 1 Guy Roux a-t-il dirigés, le record pour un entraîneur dans le championnat de France ?', 'matchs', 895, null, false, 'guy-roux', 'LFP (ligue1.com)', 'https://ligue1.com/fr/articles/l1_article_282-', false, 3, 'published'::public.question_status, '2026-10-16', null, 'Classement LFP : 895 matchs (891 avec Auxerre + Lens 2007) ; certaines sources donnent 890 pour Auxerre seul.'),
('football-p1-009', 'football', 'football', 'number'::public.question_type, 'Combien de points le PSG a-t-il récoltés en 2015-2016, le record sur une saison de Ligue 1 ?', 'points', 96, null, false, 'psg-points', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/117521-highest-points-total-in-a-single-ligue-1-season-by-a-team', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Guinness : 96 points en 2015/16 (saison à 20 clubs).'),
('football-p1-010', 'football', 'football', 'number'::public.question_type, 'Au 1er octobre 2026, combien de buts Cristiano Ronaldo avait-il marqués avec le Portugal, le record mondial en sélection ?', 'buts', 146, null, false, 'ronaldo-buts-selection', 'UEFA', 'https://www.uefa.com/european-qualifiers/news/0253-0d820b46805f-b78ccae2c451-1000--what-uefa-records-does-cristiano-ronaldo-hold/', true, 1, 'published'::public.question_status, '2026-10-16', '2027-04-16', 'Page UEFA mise à jour le 27/09/2026 : 146 buts.'),
('football-p1-011', 'football', 'football', 'number'::public.question_type, 'Au 1er octobre 2026, combien de sélections Cristiano Ronaldo comptait-il avec le Portugal, le record mondial chez les hommes ?', 'sélections', 234, null, false, 'ronaldo-selections', 'UEFA', 'https://www.uefa.com/european-qualifiers/news/0253-0d820b46805f-b78ccae2c451-1000--what-uefa-records-does-cristiano-ronaldo-hold/', true, 2, 'published'::public.question_status, '2026-10-16', '2027-04-16', 'Page UEFA mise à jour le 27/09/2026 : 234 sélections.'),
('football-p1-012', 'football', 'football', 'number'::public.question_type, 'Combien de matchs de Ligue des champions Cristiano Ronaldo a-t-il disputés, le record de la compétition ?', 'matchs', 183, null, false, 'ronaldo-ldc-matchs', 'UEFA', 'https://www.uefa.com/european-qualifiers/news/0253-0d820b46805f-b78ccae2c451-1000--what-uefa-records-does-cristiano-ronaldo-hold/', false, 2, 'published'::public.question_status, '2026-10-16', null, 'UEFA : 183 matchs (et 140 buts). Ronaldo ne joue plus la C1 depuis 2022.'),
('football-p1-013', 'football', 'football', 'number'::public.question_type, 'Combien de buts Cristiano Ronaldo a-t-il marqués lors de la Ligue des champions 2013-2014, le record sur une saison ?', 'buts', 17, null, false, 'ronaldo-ldc-saison', 'UEFA', 'https://www.uefa.com/european-qualifiers/news/0253-0d820b46805f-b78ccae2c451-1000--what-uefa-records-does-cristiano-ronaldo-hold/', false, 1, 'published'::public.question_status, '2026-10-16', null, 'UEFA : 17 buts en 2013/14, record toujours valable (Mbappé 15 en 2025/26).'),
('football-p1-014', 'football', 'football', 'number'::public.question_type, 'Combien de buts le PSG a-t-il marqués lors de la Ligue des champions 2025-2026, égalant le record d’un club sur une saison ?', 'buts', 45, null, false, 'psg-ldc-buts', 'UEFA', 'https://www.uefa.com/uefachampionsleague/news/02a5-20a9b1d54074-d4a2c11aa589-1000--champions-league-2025-26-season-in-numbers/', false, 2, 'published'::public.question_status, '2026-10-16', null, 'UEFA : 45 buts, égalant Barcelone 1999/2000 ; le PSG a conservé son titre.'),
('football-p1-015', 'football', 'football', 'number'::public.question_type, 'Combien de buts le gardien Rogério Ceni a-t-il marqués avec São Paulo, le record pour un gardien selon le Guinness ?', 'buts', 129, null, false, 'ceni', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/most-goals-scored-by-a-goalkeeper', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Guinness : 129 buts (1997-2015). Le club et la presse avancent souvent 131 : « selon le Guinness » précisé.'),
('football-p1-016', 'football', 'football', 'number'::public.question_type, 'Combien de buts Pelé a-t-il marqués en carrière (matchs amicaux compris), le record selon le Guinness ?', 'buts', 1279, null, false, 'pele-buts', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/most-career-goals-football', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Guinness : 1 279 buts en 1 363 matchs (1956-1977). D’autres décomptes donnent 1 281 ou 1 283.'),
('football-p1-017', 'football', 'football', 'number'::public.question_type, 'Combien de spectateurs ont assisté à Barcelone-Wolfsburg au Camp Nou en 2022, la plus grande affluence pour un match de club féminin ?', 'spectateurs', 91648, null, false, 'affluence-feminin', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/567892-largest-attendance-at-a-womens-football-soccer-club-match', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Guinness : 91 648 spectateurs, 22 avril 2022 (demi-finale de Ligue des champions féminine).'),
('football-p1-018', 'football', 'football', 'number'::public.question_type, 'Combien de cartons rouges ont été distribués lors de Claypole-Victoriano Arenas en 2011, le match le plus sanctionné de l’histoire ?', 'cartons', 36, null, false, 'cartons-rouges-match', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/64281-most-red-cards-in-a-football-match', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Guinness : 36 expulsions (D5 argentine, 27 février 2011), joueurs et remplaçants.'),
('football-p1-019', 'football', 'football', 'number'::public.question_type, 'Combien de buts l’AS Adema a-t-elle marqués contre le SO l’Emyrne en 2002, le score le plus fleuve de l’histoire du football ?', 'buts', 149, null, false, 'adema', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/101619-most-own-goals-in-a-domestic-league-football-match', false, 1, 'published'::public.question_status, '2026-10-16', null, 'Guinness : 149-0 à Madagascar (31/10/2002), tous contre son camp par protestation.'),
('football-p1-020', 'football', 'football', 'number'::public.question_type, 'Combien de cartons rouges le Colombien Gerardo Bedoya a-t-il reçus en carrière, le record mondial selon le Guinness ?', 'cartons', 46, null, false, 'bedoya', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/478551-most-red-cards-received-by-a-professional-football-soccer-player', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Guinness : 46 cartons rouges (1995-2015).'),
('football-p1-021', 'football', 'football', 'number'::public.question_type, 'Combien (en millions de dollars) a été vendu le maillot de la « Main de Dieu » de Maradona en 2022, le maillot de football le plus cher de l’histoire ?', 'millions de $', 8.96, null, false, 'maradona-maillot', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/most-expensive-football-shirt-sold-at-auction', false, 3, 'published'::public.question_status, '2026-10-16', null, 'Guinness : 7 142 500 £, soit environ 8 958 124 $ (Sotheby’s, 4 mai 2022).'),
('football-p1-022', 'football', 'football', 'number'::public.question_type, 'Pendant combien d’heures le Suédois Daniel Yaakob a-t-il jonglé avec un ballon en 2025, le record du monde selon le Guinness ?', 'h', 28, null, false, 'jonglage', 'Guinness World Records', 'https://www.guinnessworldrecords.com/news/2026/1/the-new-king-of-kick-ups-swedish-soccer-player-juggles-ball-for-over-24-hours-straight', true, 3, 'published'::public.question_status, '2026-10-16', '2027-04-16', 'Guinness : 28 h 21 min 2 s (Linköping, 31 mai 2025), devant Dan Magness (26 h, 2010). Réponse arrondie à 28 h.'),
('football-p1-023', 'football', 'football', 'number'::public.question_type, 'En combien de secondes Sadio Mané a-t-il réussi son triplé contre Aston Villa en 2015, le plus rapide de l’histoire de la Premier League ?', 's', 176, null, false, 'mane-triple', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/385454-fastest-hat-trick-in-a-football-soccer-english-premier-league-match', false, 3, 'published'::public.question_status, '2026-10-16', null, 'Guinness : 2 min 56 s = 176 s (16 mai 2015).'),
('football-p1-024', 'football', 'football', 'number'::public.question_type, 'En 2026, combien de titres de champion de France compte le PSG, le club le plus titré de l’histoire ?', 'titres', 14, null, false, 'psg-titres-l1', 'Hespress (AFP)', 'https://fr.hespress.com/473383-473383.html', true, 1, 'published'::public.question_status, '2026-10-16', '2027-04-16', 'PSG sacré le 13 mai 2026 : 14e titre (5e consécutif) ; Saint-Étienne 2e avec 10.'),
('football-p1-025', 'football', 'football', 'number'::public.question_type, 'En 2026, combien de Coupes de France a remportées le PSG, le record de la compétition ?', 'titres', 16, null, false, 'psg-coupe-france', 'La Libre (AFP)', 'https://www.lalibre.be/dernieres-depeches/2026/05/22/au-bout-dune-saison-de-reve-lens-tient-sa-premiere-coupe-de-france-TANEHHDAFFCDTICFGTVB7XG5JA/', true, 1, 'published'::public.question_status, '2026-10-16', '2027-04-16', '16 titres (dernier en 2025) ; l’édition 2026 a été remportée par Lens (3-1 contre Nice). OM 2e avec 10.'),
('football-p1-026', 'football', 'football', 'number'::public.question_type, 'Combien de clubs étaient engagés en Coupe de France en 2012-2013, le record de participation de la compétition ?', 'clubs', 7656, null, false, 'coupe-france-engages', 'FFF', 'https://www.fff.fr/449-progression-des-engagements.html', false, 3, 'published'::public.question_status, '2026-10-16', null, 'FFF : 7 656 clubs en 2012-2013 (7 362 en 2025-2026).'),
('football-p1-027', 'football', 'football', 'number'::public.question_type, 'Combien de buts les Bleus ont-ils marqués contre Gibraltar en novembre 2023, la plus large victoire de l’histoire de l’équipe de France ?', 'buts', 14, null, false, 'france-gibraltar', 'FFF', 'https://www.fff.fr/article/11404-la-victoire-record-des-bleus-14-0-.html', false, 1, 'published'::public.question_status, '2026-10-16', null, 'FFF : 14-0 à Nice le 18/11/2023 (ancien record 10-0 contre l’Azerbaïdjan en 1995).'),
('football-p1-028', 'football', 'football', 'number'::public.question_type, 'Combien de matchs Didier Deschamps a-t-il dirigés à la tête des Bleus (2012-2026), le record pour un sélectionneur français ?', 'matchs', 185, null, false, 'deschamps', 'Foot Mercato', 'https://www.footmercato.net/a2508593867510610322-equipe-de-france-le-bilan-statistique-impressionnant-de-didier-deschamps', false, 2, 'published'::public.question_status, '2026-10-16', null, '185 matchs (dernier : petite finale 2026). Bilan V/N/D divergent selon les sources (120-35-30 ou 122-35-30), total de 185 concordant.'),
('football-p1-029', 'football', 'football', 'number'::public.question_type, 'Combien (en millions d’euros) Chelsea a-t-il payé pour Kepa Arrizabalaga en 2018, le gardien le plus cher de l’histoire ?', 'M€', 80, null, false, 'kepa', 'Goal', 'https://www.goal.com/en-gh/news/kepas-80m-release-clause-paid-as-chelsea-seal-deal-for-courtois-replacement/utlkj9m1m2m51jky4uhf08hr7', true, 1, 'published'::public.question_status, '2026-10-16', '2027-04-16', 'Clause libératoire de 80 M€ (71,6 M£) ; aucun gardien plus cher trouvé en 2026.'),
('football-p1-030', 'football', 'football', 'number'::public.question_type, 'Selon Forbes, combien (en millions de dollars) Cristiano Ronaldo a-t-il gagné sur l’année 2025-2026, le footballeur le mieux payé du monde ?', 'millions de $', 300, null, false, 'ronaldo-forbes', 'Forbes (via Herald Corp)', 'https://biz.heraldcorp.com/article/10779646', true, 2, 'review'::public.question_status, '2026-10-16', '2027-04-16', 'Classement Forbes 2026 : 300 M$ (235 sur le terrain + 65 hors terrain), devant Messi (140). À relire : chiffre Forbes relayé par un média tiers, à confirmer sur forbes.com.'),
('football-p1-031', 'football', 'football', 'number'::public.question_type, 'Combien de matchs de Coupe du monde Lionel Messi a-t-il disputés après l’édition 2026, le record absolu de la compétition ?', 'matchs', 34, null, false, 'messi-matchs-cdm', 'FIFA', 'https://www.fifa.com/en/tournaments/mens/worldcup/articles/players-most-appearances-games-matches-history', false, 1, 'published'::public.question_status, '2026-10-16', null, 'FIFA : 34 matchs sur six éditions, devant Ronaldo (27).'),
('football-p1-032', 'football', 'football', 'number'::public.question_type, 'Combien de buts Marta a-t-elle marqués en Coupe du monde féminine, le record de la compétition ?', 'buts', 17, null, false, 'marta', 'FIFA', 'https://inside.fifa.com/fr/news/sheroes-le-discours-motivant-et-inspirant-de-marta', false, 2, 'published'::public.question_status, '2026-10-16', null, '17 buts sur cinq éditions (2003-2019), record féminin toujours valable en 2026.'),
('football-p1-033', 'football', 'football', 'number'::public.question_type, 'Combien de buts la Canadienne Christine Sinclair a-t-elle marqués en sélection, le record mondial hommes et femmes confondus ?', 'buts', 190, null, false, 'sinclair', 'NBC Sports (AP)', 'https://nbcsports.com/olympics/news/christine-sinclair-retire-soccer-canada', false, 2, 'published'::public.question_status, '2026-10-16', null, '190 buts en 327 matchs (retraite internationale fin 2023), devant Ronaldo (146 en 2026).'),
('football-p1-034', 'football', 'football', 'number'::public.question_type, 'Combien de buts Eugénie Le Sommer a-t-elle marqués avec l’équipe de France, le record des Bleues ?', 'buts', 94, null, false, 'le-sommer', 'FFF', 'https://www.fff.fr/equipe-nationale/joueur/8282-le-sommer-eugenie/fiche.html', true, 2, 'published'::public.question_status, '2026-10-16', '2027-04-16', 'Fiche FFF : 94 buts en 200 sélections (dernier match le 08/04/2025).'),
('football-p1-035', 'football', 'football', 'number'::public.question_type, 'Combien de matchs Sir Alex Ferguson a-t-il dirigés avec Manchester United, le plus long règne de l’histoire du club ?', 'matchs', 1500, null, false, 'ferguson', 'ESPN', 'https://www.espn.com/soccer/story/_/id/37387878/', false, 2, 'published'::public.question_status, '2026-10-16', null, 'ESPN : son dernier match (2013) était le 1 500e ; 38 trophées.'),
('football-p1-036', 'football', 'football', 'number'::public.question_type, 'Combien de buts Lionel Messi a-t-il marqués en Liga en 2011-2012, le record sur une saison de championnat d’Espagne ?', 'buts', 50, null, false, 'messi-liga-saison', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/most-goals-scored-in-a-season-in-the-top-division-of-spanish-football', false, 1, 'published'::public.question_status, '2026-10-16', null, 'Guinness : 50 buts en 37 matchs.'),
('football-p1-037', 'football', 'football', 'number'::public.question_type, 'Combien de matchs de Premier League Arsenal a-t-il enchaînés sans défaite (2003-2004), la plus longue série de l’histoire du championnat anglais ?', 'matchs', 49, null, false, 'invincibles', 'Arsenal FC', 'https://www.arsenal.com/feature/the-invincibles-go-49-games-unbeaten-acAhp1h7pa4V', false, 1, 'published'::public.question_status, '2026-10-16', null, '49 matchs (36 V, 13 N), de mai 2003 à octobre 2004.'),
('football-p1-038', 'football', 'football', 'number'::public.question_type, 'Combien de buts Zlatan Ibrahimović a-t-il marqués en Ligue 1 en 2015-2016, le record sur une saison pour un joueur du PSG ?', 'buts', 38, null, false, 'zlatan-psg', 'LFP (ligue1.com)', 'https://ligue1.com/fr/articles/l1_article_283-', false, 1, 'published'::public.question_status, '2026-10-16', null, 'LFP : 38 buts en 31 matchs, record du club et meilleur total depuis Skoblar (44).'),
('football-p1-039', 'football', 'football', 'number'::public.question_type, 'Combien de buts Just Fontaine a-t-il marqués lors de la Coupe du monde 1958, le record sur une seule édition ?', 'buts', 13, null, false, 'fontaine', 'FIFA', 'https://inside.fifa.com/fr/organisation/president/news/la-legende-just-fontaine-est-decedee-mais-son-record-tient-toujours', false, 1, 'published'::public.question_status, '2026-10-16', null, 'FIFA : 13 buts en six matchs ; record intact après 2026 (Mbappé 10).'),
('football-p1-040', 'football', 'football', 'number'::public.question_type, 'En quelle année France Football a-t-il décerné le premier Ballon d’or, la plus prestigieuse récompense individuelle du football ?', '', 1956, null, true, 'ballon-or-creation', 'Orange Sports', 'https://sports.orange.fr/football/autres/article/ballon-d-or-le-premier-de-l-histoire-vendu-aux-encheres-exclu-CNT000002ipMjE.html', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Premier Ballon d’or en 1956 (Stanley Matthews).'),
('football-p1-041', 'football', 'football', 'number'::public.question_type, 'En quelle année la FIFA, la plus grande fédération sportive du monde, a-t-elle été fondée à Paris ?', '', 1904, null, true, 'fifa-fondation', 'FIFA', 'https://inside.fifa.com/organisation/media-releases/fifa-celebrates-120th-anniversary-of-foundation-in-paris', false, 2, 'published'::public.question_status, '2026-10-16', null, 'FIFA : fondée le 21 mai 1904, 229 rue Saint-Honoré.'),
('football-p1-042', 'football', 'football', 'number'::public.question_type, 'En quelle année a débuté le premier championnat de France professionnel, ancêtre de la Ligue 1 ?', '', 1932, null, true, 'premier-championnat-pro', 'FFF', 'https://www.fff.fr/article/1331-les-dates-cles.html', false, 2, 'published'::public.question_status, '2026-10-16', null, 'Saison 1932-1933, remportée par l’Olympique Lillois.'),
('football-p1-043', 'football', 'football', 'number'::public.question_type, 'Quel âge avait Roger Milla lorsqu’il a marqué contre la Russie en 1994, le plus vieux buteur de l’histoire de la Coupe du monde ?', 'ans', 42, null, false, 'milla', 'FIFA', 'https://www.fifa.com/en/tournaments/mens/worldcup/canadamexicousa2026/articles/oldest-goalscorers-history-all-time', false, 1, 'published'::public.question_status, '2026-10-16', null, 'FIFA : 42 ans et 39 jours ; record intact après 2026 (Ronaldo 41 ans et 138 jours).'),
('football-p1-044', 'football', 'football', 'number'::public.question_type, 'Quel âge avait le gardien égyptien Essam El-Hadary en 2018, le plus vieux joueur de l’histoire de la Coupe du monde ?', 'ans', 45, null, false, 'el-hadary', 'FIFA', 'https://www.fifa.com/en/articles/oldest-players-appearance-history', false, 1, 'published'::public.question_status, '2026-10-16', null, '45 ans et 161 jours ; non battu en 2026 (doyen 2026 : Craig Gordon, 43 ans).'),
('football-p1-045', 'football', 'football', 'number'::public.question_type, 'Combien de spectateurs en moyenne par match la Ligue 1 a-t-elle attirés en 2024-2025, la meilleure moyenne de son histoire ?', 'spectateurs', 27948, null, false, 'affluence-l1', 'LFP (ligue1.com)', 'https://ligue1.com/fr/articles/l1_article_2576-', true, 3, 'published'::public.question_status, '2026-10-16', '2027-04-16', 'LFP : 27 948 de moyenne en 2024-25 ; 2025-26 en dessous (27 588).'),
('football-p1-046', 'football', 'football', 'number'::public.question_type, 'Combien de minutes Lionel Messi a-t-il jouées en Coupe du monde après l’édition 2026, le record de la compétition ?', 'min', 3064, null, false, 'messi-minutes-cdm', 'FIFA', 'https://www.fifa.com/en/tournaments/mens/worldcup/canadamexicousa2026/articles/lionel-messi-argentina-stats-records', false, 3, 'published'::public.question_status, '2026-10-16', null, 'FIFA : 3 064 minutes ; ESPN donne 3 054 (écart < 1 %).'),
('football-p1-047', 'football', 'football', 'number'::public.question_type, 'Pendant combien de minutes Unai Simón est-il resté invaincu en Coupe du monde (2022-2026), le record de la compétition ?', 'min', 650, null, false, 'unai-simon', 'AP (via AJC)', 'https://images.ajc.com/news/2026/07/belgium-finally-ends-unai-simons-650-minute-world-cup-shutout-streak-in-quarterfinals/', false, 3, 'published'::public.question_status, '2026-10-16', null, 'Série arrêtée par la Belgique en quart de finale le 10/07/2026 à 650 minutes (ancien record : Zenga, 517 min en 1990). Page AJC non lisible depuis l’Europe ; chiffre recoupé via RFEF et presse.'),
